import {journalLedger} from './trade-journal-core.js';
export function installJournal(){const key='tradingly-journal-v1';let data={initialBalance:500,entries:[]},panel=null;try{const old=JSON.parse(localStorage.getItem(key));if(old&&Number.isFinite(old.initialBalance)&&old.initialBalance>0&&Array.isArray(old.entries))data=old;}catch{}
const en=()=>document.documentElement.lang==='en',tr=(a,b)=>en()?b:a,escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=v=>v==null?'—':'$'+v.toLocaleString(en()?'en-US':'tr-TR',{minimumFractionDigits:2,maximumFractionDigits:2});
const style=document.createElement('style');style.textContent=`#tj-panel{position:fixed;inset:0 0 64px;z-index:900;background:#111012;color:#f5f3f3;overflow:auto;font:14px system-ui}#tj-panel[hidden]{display:none}#tj-panel *{box-sizing:border-box}#tj-panel header{position:sticky;top:0;padding:18px;background:#231f22;z-index:2;display:flex;justify-content:space-between;align-items:center}#tj-panel h2{font-size:20px;margin:0}#tj-panel main{max-width:850px;margin:auto;padding:18px}#tj-panel .card{padding:18px;border:1px solid #493b43;border-radius:18px;background:#211c20;margin-bottom:16px}#tj-panel label{display:block;color:#b6acae;font-size:12px}#tj-panel input{width:100%;min-width:0;background:#171417;border:1px solid #5d4853;color:#fff;border-radius:10px;padding:12px;margin-top:6px;font:15px system-ui}#tj-panel input:disabled{opacity:.5}#tj-panel button{background:#842c39;border:1px solid #ac4c5a;border-radius:10px;color:#fff;padding:10px 14px}#tj-panel .fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}#tj-panel .coin{grid-column:1/-1}#tj-panel details{border:1px solid #493b43;border-radius:14px;background:#211c20;margin-bottom:10px}#tj-panel summary{padding:16px;cursor:pointer;display:flex;justify-content:space-between;gap:12px;align-items:center}#tj-panel .content{padding:0 16px 16px}#tj-panel .muted{font-size:12px;color:#b6acae;line-height:1.6}#tj-panel .stats{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:16px}#tj-panel .positive{color:#70d4aa}#tj-panel .negative{color:#ee9898}#tj-panel .big{font-size:30px;color:#f39aa8;margin:8px 0}body[data-journal-open] #bt-launch{display:none}body[data-journal-open] #tl-nav button[data-page]{color:#91878b!important}body[data-journal-open] #tl-journal-tab{color:#f39aa8!important}body[data-journal-open] #tl-nav button[data-page] span:first-child{background:transparent!important}`;document.head.append(style);
function save(){try{localStorage.setItem(key,JSON.stringify(data));return true}catch{return false}}
function size(){if(panel){const nav=document.querySelector('#tl-nav');panel.style.bottom=(nav?.getBoundingClientRect().height||64)+'px'}}
function draw(){if(!panel)return;const ledger=journalLedger(data.initialBalance,data.entries),closed=ledger.filter(r=>r.closed),last=closed.at(-1),cash=last?.endingBalance??data.initialBalance;const expanded=[...panel.querySelectorAll('details[open]')].map(e=>Number(e.dataset.row));panel.innerHTML=`<header><h2>${tr('Kasa ve İşlemler','Balance & Trades')}</h2><button id="tj-close">${tr('Geri','Back')}</button></header><main><div class="card"><label>${tr('Başlangıç kasası ($)','Starting balance ($)')}<input id="tj-capital" type="number" min="0.01" step="any" value="${data.initialBalance}"></label><div class="big">${money(cash)}</div><div>${closed.length} / 100 ${tr('kapanan işlem','closed trades')}</div><p class="muted">${tr('Kayıt defteri: gerçek alış ve satış fiyatlarını sen girersin. Kasanın tamamı her işlemde kullanılır; sonraki işlem önceki kapanınca hesaplanır. Komisyon ve fonlama dahil değildir.','Trade journal: enter your actual buy and sell prices. Each trade uses the full balance; the next trade is calculated after the previous trade closes. Fees and funding are excluded.')}</p><p>${tr('Toplam kâr/zarar','Total P/L')}: <strong class="${cash>=data.initialBalance?'positive':'negative'}">${money(cash-data.initialBalance)} (${((cash/data.initialBalance-1)*100).toFixed(2)}%)</strong></p><p id="tj-save" class="muted"></p></div>${ledger.map(r=>{const e=r.entry,open=expanded.includes(r.number)||(!expanded.length&&!r.locked&&!r.closed);return `<details data-row="${r.number}" ${open?'open':''}><summary><strong>${r.number}. ${escape(e.coin)||tr('İşlem','Trade')}</strong><span class="${r.pnl>=0?'positive':'negative'}">${r.closed?r.profitPct.toFixed(2)+'% · '+money(r.endingBalance):r.locked?tr('Önceki işlem bekleniyor','Waiting for previous trade'):tr('Fiyatları gir','Enter prices')}</span></summary><div class="content"><div class="fields"><label class="coin">${tr('Coin adı','Coin name')}<input data-index="${r.number-1}" data-field="coin" value="${escape(e.coin)}" placeholder="BBUSDT" ${r.locked?'disabled':''}></label><label>${tr('Alış fiyatı','Buy price')}<input data-index="${r.number-1}" data-field="buy" type="number" min="0" step="any" value="${escape(e.buy)}" ${r.locked?'disabled':''}></label><label>${tr('Satış fiyatı','Sell price')}<input data-index="${r.number-1}" data-field="sell" type="number" min="0" step="any" value="${escape(e.sell)}" ${r.locked?'disabled':''}></label></div><div class="stats"><div>${tr('İşlem öncesi kasa','Balance before')}<br><strong>${money(r.startBalance)}</strong></div><div>${tr('Kâr oranı','Return')}<br><strong>${r.closed?r.profitPct.toFixed(2)+'%':'—'}</strong></div><div>${tr('Kâr/zarar','P/L')}<br><strong class="${r.pnl>=0?'positive':'negative'}">${money(r.pnl)}</strong></div><div>${tr('İşlem sonrası kasa','Balance after')}<br><strong>${money(r.endingBalance)}</strong></div></div>${r.closed?`<p class="muted">${escape(e.coin)} · ${tr('Alış','Buy')}: ${escape(e.buy)} · ${tr('Satış','Sell')}: ${escape(e.sell)} · ${tr('Kâr/zarar','P/L')}: ${money(r.pnl)} · ${tr('Yeni kasa','New balance')}: ${money(r.endingBalance)}</p>`:''}</div></details>`}).join('')}</main>`;panel.querySelector('#tj-close').onclick=close;panel.querySelector('#tj-capital').onchange=e=>{const n=Number(e.target.value);if(n>0&&Number.isFinite(n)){data.initialBalance=n;const ok=save();draw();saved(ok)}else e.target.value=data.initialBalance;};for(const input of panel.querySelectorAll('[data-field]'))input.onchange=e=>{const i=Number(input.dataset.index),field=input.dataset.field;data.entries[i]={...data.entries[i],[field]:field==='coin'?e.target.value.toUpperCase().trim():e.target.value};const ok=save();draw();saved(ok)};}
function saved(ok){panel.querySelector('#tj-save').textContent=ok?tr('Kaydedildi.','Saved.'):tr('Kaydedilemedi; cihaz depolamasını kontrol et.','Could not save; check device storage.')}
function close(){if(panel)panel.hidden=true;document.body.removeAttribute('data-journal-open')}
window.openTradeJournal=()=>{if(!panel){panel=document.createElement('section');panel.id='tj-panel';document.body.append(panel)}panel.hidden=false;document.body.setAttribute('data-journal-open','true');size();draw()};window.closeTradeJournal=close;window.addEventListener('resize',size);window.addEventListener('popstate',close);document.addEventListener('backbutton',e=>{if(panel&&!panel.hidden){e.preventDefault();close()}});new MutationObserver(()=>{if(panel&&!panel.hidden)draw()}).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});
}
